    ('434a12f5-3cdd-4669-9db0-4cb31fd322d4'::uuid, 'raw_data', '{"description_citations": [{"n": 1, "url": "https://en.wikipedia.org/wiki/Bejsebakke", "claim": "Bejsebakke or Sorthøj is a locality in Ansgar Parish, Fleskum Herred, Aalborg Municipality, Denmark where traces of prehistoric settlements from both the Stone Age, Bronze Age and Iron Age were found. The area have been archaeologically excavated two times. In 1958 an excavation was conducted by the National Museum of Denmark and in the years 1999 and 2000 by the Aalborg Historical Museum.", "title": "Bejsebakke", "domain": "en.wikipedia.org"}, {"n": 2, "url": "https://de.wikipedia.org/wiki/Bejsebakken", "claim": "Die Siedlung Bejsebakken war eine Glockenbechersiedlung aus dem Spätneolithikum und eine Siedlung der späten Eisenzeit", "title": "Bejsebakken", "domain": "de.wikipedia.org"}], "_description_provenance": {"v": 1, "ai": "generated", "lane": "L", "basis": "description differs from pre-March snapshot d4526691 (plan section 15.3)", "ai_system": "2026-03 enrichment chain (LLM; model per site not recorded)", "desc_sha256": "ab7e211259390db28d9243ca6e792d760fedcb5d653833b39b76945695c02af6"}}', '{"description_citations": [{"n": 2, "url": "https://de.wikipedia.org/wiki/Bejsebakken", "claim": "Die Siedlung Bejsebakken war eine Glockenbechersiedlung aus dem Spätneolithikum und eine Siedlung der späten Eisenzeit", "title": "Bejsebakken", "domain": "de.wikipedia.org"}], "_description_provenance": {"v": 1, "ai": "generated", "lane": "L", "basis": "description differs from pre-March snapshot d4526691 (plan section 15.3)", "ai_system": "2026-03 enrichment chain (LLM; model per site not recorded)", "desc_sha256": "ab7e211259390db28d9243ca6e792d760fedcb5d653833b39b76945695c02af6"}}', 'orphan-citations:434a12f5-3cdd-4669-9db0-4cb31fd322d4:raw_data', 'orphan-citations (uncited-entries): entries [1] are cited by no marker (the description cites [2]); they are removed, the cited entries stay byte for byte; the descripti