    ('8d5976d1-7cf9-4f7c-aeac-f47bacd89805'::uuid, 'raw_data', '{"description_citations": [{"n": 1, "url": "https://en.wikipedia.org/wiki/Dun_Ardtreck", "claim": "Dun Ardtreck is a D-shaped dun, or \"semi-broch\", located on the west coast of the island of Skye, in Scotland. It is located on the Minginish peninsula of Skye. It is near to the small village of Ardtreck, close to the villages of Portnalong and Fiskavaig. It is situated on a rocky knoll on the edge of a cliff overlooking the sea. The landward side of the knoll is bounded by precipitous rock faces except on the southeast where a small cleft was used for an outer gateway.", "title": "Dun Ardtreck", "domain": "en.wikipedia.org"}], "_description_provenance": {"v": 1, "ai": "generated", "lane": "L", "basis": "description differs from pre-March snapshot d4526691 (plan section 15.3)", "ai_system": "2026-03 enrichment chain (LLM; model per site not recorded)", "desc_sha256": "e2f82961471233150319f0e380caf04bbaa9acab9ea2fca053039ffa3eadbc27"}}', '{"_description_provenance": {"v": 1, "ai": "generated", "lane": "L", "basis": "description differs from pre-March snapshot d4526691 (plan section 15.3)", "ai_system": "2026-03 enrichment chain (LLM; model per site not recorded)", "desc_sha256": "e2f82961471233150319f0e380caf04bbaa9acab9ea2fca053039ffa3eadbc27"}}', 'orphan-citations:8d5976d1-7cf9-4f7c-aeac-f47bacd89805:raw_data', 'orphan-citations (citations-without-markers): the description cites no [N], so its entry [1] cites nothing; the array is removed; the description and the rest of raw_data stay as they are', 'e2f82961471233150319f0e380caf04bbaa9acab9ea2fca053039ffa3eadbc27', '[{"source": "acceptance:D1", "url": "scripts/remediation/acceptance/checks.py", "quote": "markers without an entry [], entries never cited [1]"}, {"source": "unified_sites.raw_data.description_citations", "url": "remediation_change_log.old_value", "quote": "removed: [1] ''Dun Ardtreck'' <https://en.wikipedia.org/wiki/Dun_Ardtreck> claim ''D