    ('e3af20a8-86db-43d5-9562-909cfbdf3bbd'::uuid, 'raw_data', '{"description_citations": [{"n": 1, "url": "https://en.wikipedia.org/wiki/Cueva_de_los_Casares", "claim": "Cueva de los Casares is a cave in Riba de Saelices. Discovered in 1933, it contains a number of Paleolithic cave paintings, and is most notable for a series of paintings depicting what some have argued is the earliest representation of human understanding of the reproductive process, featuring images of copulation, pregnancy, childbirth, and family life. Mammoths and other animals feature frequently in the illustrations. It was declared Bien de Interés Cultural in 1935.", "title": "Cueva de los Casares", "domain": "en.wikipedia.org"}], "_description_provenance": {"v": 1, "ai": "generated", "lane": "L", "basis": "description differs from pre-March snapshot d4526691 (plan section 15.3)", "ai_system": "2026-03 enrichment chain (LLM; model per site not recorded)", "desc_sha256": "138935f742591b4cefc9aacb0c6e9f2b197bd81b7a8619b9a716c10cb680db9a"}}', '{"_description_provenance": {"v": 1, "ai": "generated", "lane": "L", "basis": "description differs from pre-March snapshot d4526691 (plan section 15.3)", "ai_system": "2026-03 enrichment chain (LLM; model per site not recorded)", "desc_sha256": "138935f742591b4cefc9aacb0c6e9f2b197bd81b7a8619b9a716c10cb680db9a"}}', 'orphan-citations:e3af20a8-86db-43d5-9562-909cfbdf3bbd:raw_data', 'orphan-citations (citations-without-markers): the description cites no [N], so its entry [1] cites nothing; the array is removed; the description and the rest of raw_data stay as they are', '138935f742591b4cefc9aacb0c6e9f2b197bd81b7a8619b9a716c10cb680db9a', '[{"source": "acceptance:D1", "url": "scripts/remediation/acceptance/checks.py", "quote": "markers without an entry [], entries never cited [1]"}, {"source": "unified_sites.raw_data.description_citations", "url": "remediation_change_log.old_value", "quote": "removed: [1] ''Cueva de los Casares'' <https://en.wikipedia.org/wiki/Cueva_de_los_Casares> claim ''Cueva de los Casares is a cave in Riba de Saelices. Discovered in 1933, it contains a number of Paleolithic cave paintings, and is most notable for a series of paintings depicting what some have argued is the earliest representation of human understanding of the reproductive process, featuring images of copulation, pregnancy, childbirth, and family life. Mammoths and other animals feature frequently in the illustrations. It was declared Bien de Interés Cultural in 1935.''"}, {"source": "unified_sites.description", "url": "unified_sites.description", "quote": "markers []; sha256 138935f742591b4cefc9aacb0c6e9f2b197bd81b7a8619b9a716c10cb680db9a (the premise)"}, {"source": "ancient-nerds-map/src/components/SitePopup/sections/DescriptionSection.tsx", "url": "ancient-nerds-map/src/components/SitePopup/sections/DescriptionSection.tsx", "quote": "citationSources: every entry becomes a source link with its [n], whether or not a marker of the text cites it"}]'::jsonb),
