    ('fcd0bf5d-100f-451f-99b9-7d3ecb4335ec'::uuid, 'raw_data', '{"description_citations": [{"n": 1, "url": "https://en.wikipedia.org/wiki/Kukuli,_Arequipa", "claim": "Kukuli is an archaeological site with rock paintings and tombs in Peru. It is located in the Arequipa Region, Caravelí Province, Caravelí District.", "title": "Kukuli, Arequipa", "domain": "en.wikipedia.org"}], "_description_provenance": {"v": 1, "ai": "generated", "lane": "L", "basis": "description differs from pre-March snapshot d4526691 (plan section 15.3)", "ai_system": "2026-03 enrichment chain (LLM; model per site not recorded)", "desc_sha256": "f0b886dd11311056dfc2ce78e129c0792512e92da343f6270ce1955325f6d9e6"}}', '{"_description_provenance": {"v": 1, "ai": "generated", "lane": "L", "basis": "description differs from pre-March snapshot d4526691 (plan section 15.3)", "ai_system": "2026-03 enrichment chain (LLM; model per site not recorded)", "desc_sha256": "f0b886dd11311056dfc2ce78e129c0792512e92da343f6270ce1955325f6d9e6"}}', 'orphan-citations:fcd0bf5d-100f-451f-99b9-7d3ecb4335ec:raw_data', 'orphan-citations (citations-without-markers): the description cites no [N], so its entry [1] cites nothing; the array is removed; the description and the rest of raw_data stay as they are', 'f0b886dd11311056dfc2ce78e129c0792512e92da343f6270ce1955325f6d9e6', '[{"source": "acceptance:D1", "url": "scripts/remediation/acceptance/checks.py", "quote": "markers without an entry [], entries never cited [1]"}, {"source": "unified_sites.raw_data.description_citations", "url": "remediation_change_log.old_value", "quote": "removed: [1] ''Kukuli, Arequipa'' <https://en.wikipedia.org/wiki/Kukuli,_Arequipa> claim ''Kukuli is an archaeological site with rock paintings and tombs in Peru. It is located in the Arequipa Region, Caravelí Province, Caravelí District.''"}, {"source": "unified_sites.description", "url": "unified_sites.description", "quote": "markers []; sha256 f0b886dd11311056dfc2ce78e129c0792512e92da343f6270ce195532